/* 학습 해설
 * 한 cell 주소·끝을 포함하지 않는 범위 경계
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 주소가 한 cell이면 addr<=UINT32_MAX와 size<=2^32−addr를 요구합니다. [addr,addr+size) 범위의 끝이 2^32와 같아도 허용합니다. 덧셈 대신 남은 크기를 비교해 큰 size의 합산 overflow를 피하지만 주소 필드 자체의 상한도 먼저 확인합니다.
 * addr=UINT32_MAX일 때 size=1은 허용, size=2는 BADVALUE임을 계산합니다. 유효 마지막 바이트 주소와 범위의 exclusive end가 다른 숫자임을 주석에 적습니다.
 */
int fdt_appendprop_addrrange(void *fdt, int parent, int nodeoffset,
			     const char *name, uint64_t addr, uint64_t size)
{
	int addr_cells, size_cells, ret;
	uint8_t data[sizeof(fdt64_t) * 2], *prop;

	ret = fdt_address_cells(fdt, parent);
	if (ret < 0)
		return ret;
	addr_cells = ret;

	ret = fdt_size_cells(fdt, parent);
	if (ret < 0)
		return ret;
	size_cells = ret;

	/* check validity of address */
	prop = data;
	if (addr_cells == 1) {
		if ((addr > UINT32_MAX) || (((uint64_t) UINT32_MAX + 1 - addr) < size))
			return -FDT_ERR_BADVALUE;

		fdt32_st(prop, (uint32_t)addr);
	} else if (addr_cells == 2) {
		fdt64_st(prop, addr);
	} else {

/* 학습 해설
 * 두 cell 주소·64비트 인코딩과 검사의 범위
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 주소가 두 cell이면 fdt64_st로 uint64 주소를 저장합니다. 이 분기는 addr+size의 64비트 overflow나 물리 주소 범위의 적합성을 별도로 검사하지 않습니다. 값의 직렬화 성공과 장치 버스 및 실제 메모리에서 범위가 유효하다는 판단을 구별합니다.
 * addr=UINT64_MAX, size=1, 두 cell 주소/크기의 경우 helper가 인코딩 가능한 이유를 읽습니다. 실행 fixture는 바이트와 반환만 확인하며 그 주소를 실제로 매핑하지 않습니다.
 */
