		fdt32_st(prop, (uint32_t)addr);
	} else if (addr_cells == 2) {
		fdt64_st(prop, addr);
	} else {

/* 학습 해설
 * 크기 field 폭·한 cell 상한과 두 cell 저장
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 주소를 쓴 다음 prop를 addr_cells*4만큼 이동합니다. 크기가 한 cell이면 UINT32_MAX를 넘으면 BADVALUE, 두 cell이면 uint64 값을 저장하며 나머지 개수는 BADNCELLS입니다. 주소 범위 검사와 크기 field가 숫자를 담을 수 있는지는 서로 다른 조건입니다.
 * 주소 0, 크기 2^32는 한 cell 주소 범위 경계에는 맞지만 size_cells=1이면 표현할 수 없어 실패합니다. size_cells=2일 때와 비교해 두 검사를 설명합니다.
 */
int fdt_appendprop_addrrange(void *fdt, int parent, int nodeoffset,
			     const char *name, uint64_t addr, uint64_t size)
{
	int addr_cells, size_cells, ret;
	uint8_t data[sizeof(fdt64_t) * 2], *prop;

	ret = fdt_address_cells(fdt, parent);
	if (ret < 0)
		return ret;
	addr_cells = ret;

	ret = fdt_size_cells(fdt, parent);
	if (ret < 0)
		return ret;
	size_cells = ret;

	/* check validity of address */
	prop = data;
	if (addr_cells == 1) {
		if ((addr > UINT32_MAX) || (((uint64_t) UINT32_MAX + 1 - addr) < size))
			return -FDT_ERR_BADVALUE;

		fdt32_st(prop, (uint32_t)addr);
	} else if (addr_cells == 2) {
		fdt64_st(prop, addr);
	} else {

/* 학습 해설
 * 주소·크기 byte 직렬화와 append 반환
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 최대 16바이트의 지역 uint8 배열에 주소 뒤 크기를 big-endian으로 저장합니다. fdt32_st/fdt64_st의 byte 저장 방식은 배열을 정렬된 typed pointer로 직접 역참조하는 것과 다릅니다. 실제 추가 길이는 (addr_cells+size_cells)*4이며 append의 반환을 그대로 전달합니다.
 * 1/1이면 8, 2/1이면 12, 2/2이면 16바이트를 계산합니다. 원본의 지역 배열은 helper 호출 동안만 유효하므로 append가 동기적으로 데이터를 사용하는 API 계약을 확인합니다.
 */
int fdt_appendprop_addrrange(void *fdt, int parent, int nodeoffset,
			     const char *name, uint64_t addr, uint64_t size)
{
	int addr_cells, size_cells, ret;
	uint8_t data[sizeof(fdt64_t) * 2], *prop;

	ret = fdt_address_cells(fdt, parent);
	if (ret < 0)
		return ret;
	addr_cells = ret;

	ret = fdt_size_cells(fdt, parent);
	if (ret < 0)
		return ret;
	size_cells = ret;

	/* check validity of address */
	prop = data;
	if (addr_cells == 1) {
		if ((addr > UINT32_MAX) || (((uint64_t) UINT32_MAX + 1 - addr) < size))
			return -FDT_ERR_BADVALUE;

		fdt32_st(prop, (uint32_t)addr);
	} else if (addr_cells == 2) {
		fdt64_st(prop, addr);
	} else {

/* 학습 해설
 * 빈 DTB 생성·여섯 단계의 순차 구성
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * wrapper는 create→finish_reservemap→begin_node(빈 이름)→end_node→finish→open_into를 순서대로 호출합니다. 예약 목록을 끝낸 뒤 빈 root 하나를 작성해 완성하고 마지막에 편집용 buffer 형태로 엽니다. 원본 wrapper의 흐름과 호출되는 각 구현의 내부 알고리즘을 구별합니다.
 * 여섯 호출을 화살표로 그려 tree 상태를 설명합니다. fixture는 호출 순서와 인자를 확인하는 provider이며 실제 DTB 바이트를 생성하는 하위 구현을 실행한 증거는 아닙니다.
 */
int fdt_create_empty_tree(void *buf, int bufsize)
{
	int err;

	err = fdt_create(buf, bufsize);
	if (err)
		return err;

	err = fdt_finish_reservemap(buf);
	if (err)
		return err;

	err = fdt_begin_node(buf, "");
	if (err)
		return err;

	err =  fdt_end_node(buf);
	if (err)
		return err;

	err = fdt_finish(buf);
	if (err)
		return err;

	return fdt_open_into(buf, buf, bufsize);
}

/* 학습 해설
 * 빈 트리 오류 처리·첫 실패에서 즉시 반환
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 각 중간 단계의 err가 0이 아니면 즉시 반환하고 다음 단계는 호출하지 않습니다. 음수만 비교하는 것이 아니라 if(err)입니다. wrapper 자체는 앞 단계가 변경한 buffer를 원래 상태로 되돌리는 별도 코드를 갖지 않습니다. 하위 함수의 구체적인 실패 상태는 그 구현에서 확인해야 합니다.
 * 실패를 여섯 단계마다 주입해 호출 수와 반환을 확인합니다. provider가 이미 적은 marker는 남으며 이를 실제 모든 하위 함수의 실패 후 DTB 형식으로 일반화하지 않습니다.
 */
int fdt_create_empty_tree(void *buf, int bufsize)
{
	int err;

	err = fdt_create(buf, bufsize);
	if (err)
		return err;

	err = fdt_finish_reservemap(buf);
	if (err)
		return err;

	err = fdt_begin_node(buf, "");
	if (err)
		return err;

	err =  fdt_end_node(buf);
	if (err)
		return err;

	err = fdt_finish(buf);
	if (err)
		return err;

	return fdt_open_into(buf, buf, bufsize);
}

/* 학습 해설
 * 완성 뒤 self open·같은 buffer와 여유 크기
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 마지막 호출은 fdt_open_into(buf,buf,bufsize)로 source와 destination이 같습니다. 완성 후 제공한 용량에서 편집 가능한 형태로 여는 요청이며 그 결과를 그대로 반환합니다. 실제 block 이동과 여유 공간 처리 알고리즘은 open_into의 구현에서 설명할 항목입니다.
 * 처음 create의 bufsize와 마지막 open_into의 bufsize가 같은 것을 확인합니다. wrapper에서 buffer를 새로 할당하거나 반환 pointer를 교체하는 코드가 없다는 점을 주석에 적습니다.
 */
int fdt_create_empty_tree(void *buf, int bufsize)
{
	int err;

	err = fdt_create(buf, bufsize);
	if (err)
		return err;

	err = fdt_finish_reservemap(buf);
	if (err)
		return err;

	err = fdt_begin_node(buf, "");
	if (err)
		return err;

	err =  fdt_end_node(buf);
	if (err)
		return err;

	err = fdt_finish(buf);
	if (err)
		return err;

	return fdt_open_into(buf, buf, bufsize);
}

/* 학습 해설
 * 오류 문자열·양수 성공 위치와 0 성공
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * errval>0이면 valid offset/length 문자열, 0이면 no error 문자열을 반환합니다. 일부 libfdt API의 성공 값은 위치나 길이이며 모든 성공이 0이라는 규칙은 아닙니다. fdt_strerror는 설명을 고를 뿐 해당 offset이 실제 트리에서 유효한지를 검증하지 않습니다.
 * 0, 1, INT_MAX의 문자열 결과를 비교합니다. 사용 중인 API의 성공 반환 계약을 먼저 읽고 문자열 helper의 부호 분류를 연결합니다.
 */
const char *fdt_strerror(int errval)
{
	if (errval > 0)
		return "<valid offset/length>";
	else if (errval == 0)
		return "<no error>";
	else if (-errval < FDT_ERRTABSIZE) {
		const char *s = fdt_errtable[-errval].str;

		if (s)
			return s;
	}

	return "<unknown error>";
}

/* 학습 해설
 * 음수 오류 lookup·범위와 알 수 없는 값
 * 장치 트리의 부모·자식 주소 형식, endian 직렬화, 경계 검사, 순차 생성과 오류 전달, C 지정 초기화와 오류 해석을 원본으로 공부합니다.
 * 음수이면 -errval을 table index로 사용하되 table 크기 미만인지와 항목의 str가 존재하는지를 확인합니다. 알려진 오류는 상수 이름, 그 외는 unknown error 문자열입니다. INT_MIN에 unary minus를 적용하는 signed overflow는 이 원본의 별도 경계 문제이며 fixture는 그 값을 실행하지 않았습니다.
 * -BADNCELLS, -ALIGNMENT, -1000의 결과를 풉니다. table bounds 검사와 int negation의 표현 가능성을 별개의 조건으로 읽어 모든 int 입력의 안전성을 주장하지 않습니다.
 */
const char *fdt_strerror(int errval)
{
	if (errval > 0)
		return "<valid offset/length>";
	else if (errval == 0)
		return "<no error>";
	else if (-errval < FDT_ERRTABSIZE) {
		const char *s = fdt_errtable[-errval].str;

		if (s)
			return s;
	}

	return "<unknown error>";
}

/* 학습 해설
 * DTB 제자리 부분 수정·이름 길이와 byte index
 * DTB 제자리 수정의 길이 계약, byte index와 정수 경계, NOP을 이용한 offset 보존, 깊이 순회와 subtree 무효화의 원리를 읽습니다.
 * 이 helper는 name의 앞 namelen 문자로 property를 조회하고 idx 바이트부터 len 바이트를 덮어씁니다. 문자열이 NUL로 끝나지 않는 일부 이름 표현에도 사용할 수 있습니다. idx는 cell 번호가 아니라 char pointer에 더하는 byte offset이며 기존 property의 길이와 다른 block의 위치는 유지합니다.
 * 길이 8 property에서 두 번째 32비트 cell을 바꾸려면 idx=4, len=4를 사용합니다. answer-extra와 namelen=6으로 answer를 선택하는 provider 사례를 읽되 실제 이름 검색 알고리즘은 별도 원본에서 공부합니다.
 */
int fdt_setprop_inplace_namelen_partial(void *fdt, int nodeoffset,
					const char *name, int namelen,
					uint32_t idx, const void *val,
					int len)
{
	void *propval;
	int proplen;

	propval = fdt_getprop_namelen_w(fdt, nodeoffset, name, namelen,
					&proplen);
	if (!propval)
		return proplen;

	if ((unsigned)proplen < (len + idx))
		return -FDT_ERR_NOSPACE;

	memcpy((char *)propval + idx, val, len);
	return 0;
}

int fdt_setprop_inplace(void *fdt, int nodeoffset, const char *name,
			const void *val, int len)
{
	const void *propval;
	int proplen;

/* 학습 해설
 * DTB 부분 수정·조회 실패와 쓰기 전 검사
 * DTB 제자리 수정의 길이 계약, byte index와 정수 경계, NOP을 이용한 offset 보존, 깊이 순회와 subtree 무효화의 원리를 읽습니다.
 * writable 조회 결과가 NULL이면 proplen에 담긴 오류를 그대로 반환합니다. 조회가 성공하면 (unsigned)proplen과 len+idx를 비교해 공간 부족이면 NOSPACE를 반환하고 memcpy는 실행하지 않습니다. fixture의 작은 비음수 길이 범위에서는 마지막 byte와 빈 끝 범위까지 독립 oracle로 대조했습니다.
 * proplen=8에서 idx=6,len=2는 성공, len=3은 실패임을 풉니다. 실패 때 같은 buffer snapshot과 비교해 이 helper가 쓰기 전에 반환한 경로를 확인합니다.
 */
int fdt_setprop_inplace_namelen_partial(void *fdt, int nodeoffset,
					const char *name, int namelen,
					uint32_t idx, const void *val,
					int len)
{
	void *propval;
	int proplen;

	propval = fdt_getprop_namelen_w(fdt, nodeoffset, name, namelen,
					&proplen);
	if (!propval)
		return proplen;

	if ((unsigned)proplen < (len + idx))
		return -FDT_ERR_NOSPACE;

	memcpy((char *)propval + idx, val, len);
	return 0;
}

int fdt_setprop_inplace(void *fdt, int nodeoffset, const char *name,
			const void *val, int len)
{
	const void *propval;
	int proplen;

/* 학습 해설
 * DTB 부분 수정·unsigned 합산의 사용 경계
 * DTB 제자리 수정의 길이 계약, byte index와 정수 경계, NOP을 이용한 offset 보존, 깊이 순회와 subtree 무효화의 원리를 읽습니다.
 * idx가 uint32이고 len은 int이므로 len+idx는 unsigned 산술 문맥입니다. 이 원본의 비교에는 별도의 덧셈 wrap 검사나 len<0 guard가 없습니다. 작은 유효 범위의 성공 검산을 임의 인자의 안전성 증명으로 확장하지 않고 표현 가능한 비음수 길이와 실제 accessible buffer 조건을 함께 확인합니다.
 * UINT32_MAX+1u가 0이 되는 산술을 쓰기 없이 계산합니다. fixture는 wrap index를 memcpy에 전달하지 않았습니다. overlap val에는 memcpy 계약도 고려해야 하며 memmove와 동일하게 읽지 않습니다.
 */
int fdt_setprop_inplace_namelen_partial(void *fdt, int nodeoffset,
					const char *name, int namelen,
					uint32_t idx, const void *val,
					int len)
{
	void *propval;
	int proplen;

	propval = fdt_getprop_namelen_w(fdt, nodeoffset, name, namelen,
					&proplen);
	if (!propval)
		return proplen;

	if ((unsigned)proplen < (len + idx))
		return -FDT_ERR_NOSPACE;

