static void *fdt_grab_space_(void *fdt, size_t len)
{
	unsigned int offset = fdt_size_dt_struct(fdt);
	unsigned int spaceleft;

	spaceleft = fdt_totalsize(fdt) - fdt_off_dt_struct(fdt)
		- fdt_size_dt_strings(fdt);

	if ((offset + len < offset) || (offset + len > spaceleft))
		return NULL;

	fdt_set_size_dt_struct(fdt, offset + len);
	return fdt_offset_ptr_w_(fdt, offset);
}

/* 학습 해설
 * DTB 공간 확보·앞 structure와 뒤 strings 사이
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * structure는 앞에서 증가하고 strings는 buffer 끝에서 역방향 증가합니다. grab_space는 총 공간에서 structure 시작과 문자열 크기를 빼고 현재 structure size+len이 남은 공간 안인지 및 합산 wrap를 검사합니다. 성공이면 크기를 늘리고 이전 structure 끝 pointer를 반환합니다.
 * 앞 header/reserve와 뒤 strings 사이의 빈 구간을 그림으로 적습니다. 실패 시 크기를 늘리지 않는 순서와 byte 단위를 확인합니다.
 */
static void *fdt_grab_space_(void *fdt, size_t len)
{
	unsigned int offset = fdt_size_dt_struct(fdt);
	unsigned int spaceleft;

	spaceleft = fdt_totalsize(fdt) - fdt_off_dt_struct(fdt)
		- fdt_size_dt_strings(fdt);

	if ((offset + len < offset) || (offset + len > spaceleft))
		return NULL;

	fdt_set_size_dt_struct(fdt, offset + len);
	return fdt_offset_ptr_w_(fdt, offset);
}

int fdt_create_with_flags(void *buf, int bufsize, uint32_t flags)
{
	const int hdrsize = FDT_ALIGN(sizeof(struct fdt_header),
				      sizeof(struct fdt_reserve_entry));
	void *fdt = buf;

	if (bufsize < hdrsize)
		return -FDT_ERR_NOSPACE;

	if (flags & ~FDT_CREATE_FLAGS_ALL)
		return -FDT_ERR_BADFLAGS;

/* 학습 해설
 * DTB create·header와 reserve entry 정렬
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * header 크기를 reserve entry 크기16의 배수로 올려40→48을 얻습니다. buffer가48보다 작으면 NOSPACE, 알려지지 않은 flag bit가 있으면 BADFLAGS입니다. 이 검사를 통과한 뒤 전체 bufsize를 0으로 채우고 작성 header를 설정합니다. 이 최소48은 완성 root tree 전체가 들어가는 크기와 다릅니다.
 * 47 실패/48 초기화 가능을 비교하고 빈 tree 완성에는 terminator/root/END가 추가로 필요함을 계산합니다. 오류 전 buffer snapshot이 유지되는 fixture를 확인합니다.
 */
int fdt_create_with_flags(void *buf, int bufsize, uint32_t flags)
{
	const int hdrsize = FDT_ALIGN(sizeof(struct fdt_header),
				      sizeof(struct fdt_reserve_entry));
	void *fdt = buf;

	if (bufsize < hdrsize)
		return -FDT_ERR_NOSPACE;

	if (flags & ~FDT_CREATE_FLAGS_ALL)
		return -FDT_ERR_BADFLAGS;

	memset(buf, 0, bufsize);

	/*
	 * magic and last_comp_version keep intermediate state during the fdt
	 * creation process, which is replaced with the proper FDT format by
	 * fdt_finish().
	 *
	 * flags should be accessed with sw_flags().
	 */
	fdt_set_magic(fdt, FDT_SW_MAGIC);
	fdt_set_version(fdt, FDT_LAST_SUPPORTED_VERSION);
	fdt_set_last_comp_version(fdt, flags);

	fdt_set_totalsize(fdt,  bufsize);

/* 학습 해설
 * DTB create·기본 flag와 초기 header 값
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * fdt_create는 create_with_flags의 flags0 wrapper입니다. 작성 magic, 최신 version17, lastcomp에는 flags, total에는 capacity, reserve/structure 시작에는48, strings marker에는0이 설정됩니다. structure와 strings 크기는 먼저 전체 buffer를 0으로 채운 상태에서 시작합니다.
 * 초기 total256과 최종 compact total을 비교합니다. 반환0은 초기화 성공이며 아직 소비할 완성 DTB가 아님을 적습니다.
 */
int fdt_create(void *buf, int bufsize)
{
	return fdt_create_with_flags(buf, bufsize, 0);
}

