/* 학습 해설
 * DTB reserve entry·64비트 주소와 크기의 저장
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * 예약 단계에서 현재 structure 시작 위치에16바이트 entry를 씁니다. 주소와 크기를 각각 big-endian64로 저장하고 structure 시작을16 증가시킵니다. 이 기록은 OS에 예약 정보를 전달하는 자료 표현이며 함수 호출 자체가 물리 page allocator에서 메모리를 예약하지는 않습니다.
 * addr0x1000/size0x200을 실제 생성 DTB의48/56 offset에서 읽어 대조합니다. entry 수와 struct offset의 관계를 계산합니다.
 */
int fdt_add_reservemap_entry(void *fdt, uint64_t addr, uint64_t size)
{
	struct fdt_reserve_entry *re;
	int offset;

	FDT_SW_PROBE_MEMRSV(fdt);

	offset = fdt_off_dt_struct(fdt);
	if ((offset + sizeof(*re)) > fdt_totalsize(fdt))
		return -FDT_ERR_NOSPACE;

	re = (struct fdt_reserve_entry *)((char *)fdt + offset);
	re->address = cpu_to_fdt64(addr);
	re->size = cpu_to_fdt64(size);

	fdt_set_off_dt_struct(fdt, offset + sizeof(*re));

	return 0;
}

int fdt_finish_reservemap(void *fdt)
{
	int err = fdt_add_reservemap_entry(fdt, 0, 0);

	if (err)
		return err;

/* 학습 해설
 * DTB reserve 종료·0/0 terminator와 phase 전이
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * 종료는 add_reservemap_entry(0,0)를 호출해 terminator를 쓰고 성공일 때 strings marker를 totalsize로 바꿉니다. terminator 공간도16바이트 필요합니다. 실패면 marker를 바꾸지 않고 해당 오류를 반환하므로 예약 작성 상태와 structure 단계의 전이를 성공 여부와 연결합니다.
 * 64바이트 buffer에서 첫 entry 뒤 terminator가 부족한 사례를 풉니다. 성공 fixture의0/0 entry를 독립 load로 확인합니다.
 */
int fdt_finish_reservemap(void *fdt)
{
	int err = fdt_add_reservemap_entry(fdt, 0, 0);

	if (err)
		return err;

	fdt_set_off_dt_strings(fdt, fdt_totalsize(fdt));
	return 0;
}

int fdt_begin_node(void *fdt, const char *name)
{
	struct fdt_node_header *nh;
	int namelen;

	FDT_SW_PROBE_STRUCT(fdt);

	namelen = strlen(name) + 1;
	nh = fdt_grab_space_(fdt, sizeof(*nh) + FDT_TAGALIGN(namelen));
	if (! nh)
		return -FDT_ERR_NOSPACE;

	nh->tag = cpu_to_fdt32(FDT_BEGIN_NODE);
	memcpy(nh->name, name, namelen);
	return 0;

/* 학습 해설
 * DTB node 시작·NUL 이름과 4바이트 padding
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * node 시작은 structure phase 검사 뒤 strlen(name)+1을 구하고 tag header와 이름을4바이트 정렬한 공간을 확보합니다. BEGIN_NODE를 big-endian으로 쓰고 이름은 NUL까지 복사합니다. 별도 child depth counter를 이 함수가 유지하는 것은 아니므로 호출자가 올바른 nesting 순서를 만들어야 합니다.
 * 빈 root는 tag4+정렬된 빈 이름4로8바이트입니다. a도 이름2가4로 정렬돼8인 실제 offset을 계산합니다.
 */
int fdt_begin_node(void *fdt, const char *name)
{
	struct fdt_node_header *nh;
	int namelen;

	FDT_SW_PROBE_STRUCT(fdt);

	namelen = strlen(name) + 1;
	nh = fdt_grab_space_(fdt, sizeof(*nh) + FDT_TAGALIGN(namelen));
	if (! nh)
		return -FDT_ERR_NOSPACE;

	nh->tag = cpu_to_fdt32(FDT_BEGIN_NODE);
	memcpy(nh->name, name, namelen);
	return 0;
}

int fdt_end_node(void *fdt)
{
	fdt32_t *en;

	FDT_SW_PROBE_STRUCT(fdt);

	en = fdt_grab_space_(fdt, FDT_TAGSIZE);
	if (! en)
		return -FDT_ERR_NOSPACE;

/* 학습 해설
 * DTB node 종료·고정 END_NODE tag
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * node 종료는 structure phase와4바이트 공간을 확인해 END_NODE를 씁니다. 이름이나 길이 field는 없습니다. phase 검사 자체가 matching BEGIN_NODE의 깊이를 세는 검사라고 해석하지 않고 caller가 올바른 계층을 유지해야 합니다.
 * root→child→child end→root end 순서를 적습니다. END_NODE와 전체 structure 끝의 FDT_END를 구별해 주석을 답니다.
 */
int fdt_end_node(void *fdt)
{
	fdt32_t *en;

	FDT_SW_PROBE_STRUCT(fdt);

	en = fdt_grab_space_(fdt, FDT_TAGSIZE);
	if (! en)
		return -FDT_ERR_NOSPACE;

	*en = cpu_to_fdt32(FDT_END_NODE);
	return 0;
}

static int fdt_add_string_(void *fdt, const char *s)
{
	char *strtab = (char *)fdt + fdt_totalsize(fdt);
	unsigned int strtabsize = fdt_size_dt_strings(fdt);
	unsigned int len = strlen(s) + 1;
	unsigned int struct_top, offset;

	offset = strtabsize + len;
	struct_top = fdt_off_dt_struct(fdt) + fdt_size_dt_struct(fdt);
	if (fdt_totalsize(fdt) - offset < struct_top)
		return 0; /* no more room :( */

/* 학습 해설
 * DTB 문자열 추가·buffer 끝에서 역방향 성장
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * strtab 기준은 작성 buffer의 끝입니다. 기존 크기에 strlen(s)+1을 더한 offset을 확보하고 그만큼 뒤로 간 곳에 NUL 문자열을 씁니다. 성공은 음수 offset, 실패는0을 반환합니다. 작성 property의 nameoff는 이 임시 기준으로 저장되며 최종 strings 시작 기준과 다릅니다.
 * answer 길이7이면 첫 offset은-7입니다. 문자열 크기와 structure 끝의 충돌 조건을 읽고 bounded NUL 문자열 및 표현 가능한 길이의 caller 계약을 확인합니다.
 */
static int fdt_add_string_(void *fdt, const char *s)
{
	char *strtab = (char *)fdt + fdt_totalsize(fdt);
	unsigned int strtabsize = fdt_size_dt_strings(fdt);
	unsigned int len = strlen(s) + 1;
	unsigned int struct_top, offset;

	offset = strtabsize + len;
	struct_top = fdt_off_dt_struct(fdt) + fdt_size_dt_struct(fdt);
	if (fdt_totalsize(fdt) - offset < struct_top)
		return 0; /* no more room :( */

	memcpy(strtab - offset, s, len);
	fdt_set_size_dt_strings(fdt, strtabsize + len);
	return -offset;
}

/* Must only be used to roll back in case of error */
static void fdt_del_last_string_(void *fdt, const char *s)
{
	int strtabsize = fdt_size_dt_strings(fdt);
	int len = strlen(s) + 1;

	fdt_set_size_dt_strings(fdt, strtabsize - len);
}

/* 학습 해설
 * DTB 문자열 dedup·suffix 재사용과 allocated
 * DTB 순차 생성의 상태 전이, 양끝 buffer 성장, 겹침 이동, big-endian record, 이름 재사용과 rollback, offset 기준 변환을 원본으로 공부합니다.
 * 현재 stringtable에서 NUL까지 같은 byte sequence를 찾으면 기존 음수 offset을 반환하고 allocated0을 유지합니다. 못 찾으면 allocated1로 새 문자열을 추가합니다. byte 검색은 문자열 시작뿐 아니라 suffix도 재사용할 수 있어 foobar 속의 bar 위치가 결과가 됩니다.
 * 서로 다른 node의 foobar/bar 이름을 생성해 최종 table7바이트와 nameoff0/3을 확인합니다. 중복 property 이름인지와 string storage 재사용인지를 구별합니다.
 */
static int fdt_find_add_string_(void *fdt, const char *s, int *allocated)
{
	char *strtab = (char *)fdt + fdt_totalsize(fdt);
	int strtabsize = fdt_size_dt_strings(fdt);
	const char *p;

	*allocated = 0;

	p = fdt_find_string_(strtab - strtabsize, strtabsize, s);
	if (p)
		return p - strtab;

	*allocated = 1;

	return fdt_add_string_(fdt, s);
}

